import { GradientInput, type GradientValue } from '@levain/ui-react';
import { useState } from 'react';

export default function FillExample() {
  const [fill, setFill] = useState<GradientValue>({
    angle: 90,
    stops: [
      { position: 0, color: { hex: '#5C62D6', alpha: 100 } },
      { position: 100, color: { hex: '#E86A92', alpha: 100 } },
    ],
  });

  return <GradientInput label="Fill" value={fill} onChange={setFill} size="sm" />;
}
